const listActionItemsBySeller = `-- name: ListActionItemsBySeller :many
SELECT
    ai.id, ai.seller_account_id, ai.run_id, ai.action_key, ai.type, ai.category, ai.priority, ai.title, ai.summary, ai.reason, ai.next_step, ai.expected_effect, ai.evidence_json, ai.limitations_json, ai.cta_json, ai.affected_entities_json, ai.entity_group_ref, ai.source_candidate_ids_json, ai.evidence_fact_ids_json, ai.payload_json, ai.metric_date, ai.created_at, ai.updated_at,
    COALESCE(aus.status, 'open')::text AS user_status,
    aus.checked_at,
    aus.snoozed_until,
    aus.dismissed_at
FROM action_items ai
LEFT JOIN action_user_states aus
    ON aus.seller_account_id = ai.seller_account_id
    AND aus.action_key = ai.action_key
WHERE ai.seller_account_id = $1
  AND (
    $2::date IS NULL
    OR ai.metric_date = $2::date
  )
  AND (
    $3::text IS NULL
    OR ai.category = $3::text
  )
  AND (
    $4::text IS NULL
    OR ai.priority = $4::text
  )
  AND (
    $5::text IS NULL
    OR $5::text = 'all'
    OR (
      $5::text = 'open'
      AND COALESCE(aus.status, 'open') = 'open'
    )
    OR (
      $5::text = 'checked'
      AND aus.status = 'checked'
    )
    OR (
      $5::text = 'snoozed'
      AND aus.status = 'snoozed'
    )
    OR (
      $5::text = 'dismissed'
      AND aus.status = 'dismissed'
    )
  )
ORDER BY
    CASE ai.priority
        WHEN 'critical' THEN 1
        WHEN 'important' THEN 2
        WHEN 'watch' THEN 3
        ELSE 4
    END,
    ai.created_at DESC
LIMIT $7
OFFSET $6
`

